INSERT INTO "mock_exams" ("id", "exam_code", "title", "description", "questions", "targets", "unlock_date", "status", "created_by", "created_at", "updated_at") VALUES (5, '123', 'test 2', '123', '{"settings":{"fontSize":16,"fontFamily":"''Inter'', sans-serif"},"questions":[{"id":"1786705661819","text":"2 + 2","type":"question","image":null,"points":1,"options":[{"id":"17867056618191","text":"4","isCorrect":true},{"id":"17867056618192","text":"1","isCorrect":false},{"id":"17867056618193","text":"Option 3","isCorrect":false}],"questionType":"Multiple Choice"},{"id":"1786705671419","text":"1 + 1 ","type":"question","image":null,"points":1,"options":[{"id":"17867056714191","text":"2","isCorrect":true},{"id":"17867056714192","text":"1","isCorrect":false},{"id":"17867056714193","text":"Option 3","isCorrect":false}],"questionType":"Multiple Choice"}]}'::jsonb, '["batch1","batch1-lept","batch1-lept-bsed-english","batch1-lept-bsed-math","batch1-lept-bsed-science","batch1-lept-bsed-filipino","batch1-lept-bsed-socstudies","batch1-lept-beed","batch2-lept","batch2-lept-bsed-english","batch2-lept-bsed-math","batch2-lept-bsed-science","batch2-lept-bsed-filipino","batch2-lept-bsed-socstudies","batch2-lept-beed","batch2","batch8","batch8-lept"]'::jsonb, NULL, 'active', 1, '2026-08-14T11:07:37.732Z', '2026-08-14T11:08:11.850Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO "mock_exams" ("id", "exam_code", "title", "description", "questions", "targets", "unlock_date", "status", "created_by", "created_at", "updated_at") VALUES (3, 'LEPT-2026-ME-B1', 'AUGUST: MOCK EXAM I', NULL, '{"settings":{"fontSize":18,"fontFamily":"''Open Sans'', sans-serif"},"questions":[{"id":"1786513363495","text":"Teacher Maria asks her students to analyze a historical document, identify the author''s underlying assumptions, and evaluate the evidence presented before drawing a conclusion. Which level of Bloom’s Taxonomy is primary being utilized?","type":"question","image":null,"points":10,"options":[{"id":"17865133634951","text":"Application","isCorrect":false},{"id":"17865133634952","text":"Analysis","isCorrect":true},{"id":"17865133634953","text":"Comprehension","isCorrect":false},{"id":"1786514705231","text":"Knowledge","isCorrect":false}],"questionType":"Multiple Choice"},{"id":"1786514723170","text":"While reading a dense textbook chapter on educational psychology, John routinely stops at the end of each section to ask himself: \"Did I understand what I just read, or do I need to re-read it?\" What learning process is John demonstrating?","type":"question","image":null,"points":10,"options":[{"id":"17865147231701","text":"Metacognition","isCorrect":true},{"id":"17865147231702","text":"Scaffolding","isCorrect":false},{"id":"17865147231703","text":"Assimilation","isCorrect":false},{"id":"1786514743491","text":"Conditioning","isCorrect":false}],"questionType":"Multiple Choice"},{"id":"1786514752642","text":"During a class debate, a student argues: \"We shouldn''t accept Teacher Mark''s proposal for the new study schedule because he is always late to class anyway.\" Which logical fallacy is present in this argument?","type":"question","image":null,"points":10,"options":[{"id":"17865147526421","text":"Argumentum ad Populum (Appeal to the People)","isCorrect":false},{"id":"17865147526422","text":"Argumentum ad Misericordiam (Appeal to Pity)","isCorrect":false},{"id":"17865147526423","text":"Argumentum ad Hominem (Attacking the Person)","isCorrect":true},{"id":"1786514779635","text":"Non Sequitur","isCorrect":false}],"questionType":"Multiple Choice"},{"id":"1786514788203","text":"In the SQ3R study method, what does the first \"R\" stand for, and when should it be performed?","type":"question","image":null,"points":10,"options":[{"id":"17865147882031","text":"Recite","isCorrect":false},{"id":"17865147882032","text":"Read","isCorrect":true},{"id":"17865147882033","text":"Review","isCorrect":false},{"id":"1786514812027","text":"Reflect","isCorrect":false}],"questionType":"Multiple Choice"},{"id":"1786514828396","text":"Which note-taking strategy divides a sheet of paper into three sections: a narrow left column for cues/keywords, a large right column for main notes, and a bottom section for a summary?","type":"question","image":null,"points":10,"options":[{"id":"17865148283961","text":"Mind Mapping / Concept Mapping","isCorrect":false},{"id":"17865148283962","text":"Outlining Method","isCorrect":false},{"id":"17865148283963","text":"Cornell Method","isCorrect":true},{"id":"1786514848068","text":"Charting Method","isCorrect":false}],"questionType":"Multiple Choice"},{"id":"1786514855116","text":"Consider the following statements:  Premise 1: All professional teachers passed the LEPT.  Premise 2: Sarah is a professional teacher.  Conclusion: Therefore, Sarah passed the LEPT.","type":"question","image":null,"points":10,"options":[{"id":"17865148551161","text":"Inductive Reasoning","isCorrect":false},{"id":"17865148551162","text":"Deductive Reasoning","isCorrect":true},{"id":"17865148551163","text":"Analogical Reasoning","isCorrect":false},{"id":"1786514884062","text":"Abductive Reasoning","isCorrect":false}],"questionType":"Multiple Choice"},{"id":"1786514890117","text":"A researcher observes that every time rain falls, traffic congestion increases in the city. From this repeated observation, she concludes: \"Rain always causes traffic jams in this city.\" This is an example of:","type":"question","image":null,"points":10,"options":[{"id":"17865148901171","text":"Deductive logic starting from a universal truth","isCorrect":false},{"id":"17865148901172","text":"Inductive logic moving from specific observations to a general conclusion","isCorrect":true},{"id":"17865148901173","text":"Syllogistic logic using major and minor premises","isCorrect":false},{"id":"1786514916110","text":"Intuitive reasoning based on subjective emotion","isCorrect":false}],"questionType":"Multiple Choice"},{"id":"1786514923862","text":"When synthesizing multiple sources for an academic research paper, which of the following practices represents the highest level of critical thinking?","type":"question","image":null,"points":10,"options":[{"id":"17865149238621","text":"Copying paragraphs directly from three different journals and combining them.","isCorrect":false},{"id":"17865149238622","text":"Summarizing each source separately in sequential order without comparing them.","isCorrect":false},{"id":"17865149238623","text":"Identifying overlapping arguments, contrasting perspectives, and drawing a original conclusion.","isCorrect":true},{"id":"1786514944727","text":"Choosing only the sources that agree with your personal bias and ignoring the rest.","isCorrect":false}],"questionType":"Multiple Choice"},{"id":"1786514949735","text":"Which type of graphic organizer is best suited for comparing and contrasting two distinct theories of child development?","type":"question","image":null,"points":10,"options":[{"id":"17865149497351","text":"Venn Diagram","isCorrect":true},{"id":"17865149497352","text":"Fishbone Diagram","isCorrect":false},{"id":"17865149497353","text":"Flowchart","isCorrect":false},{"id":"1786514976776","text":"KWL Chart","isCorrect":false}],"questionType":"Multiple Choice"},{"id":"1786514979007","text":"A student who struggles with time management decides to study for 25 minutes uninterrupted, followed by a 5-minute break, repeating this cycle four times before taking a longer break. What study technique is this?","type":"question","image":null,"points":10,"options":[{"id":"17865149790071","text":"Leitner Box System","isCorrect":false},{"id":"17865149790072","text":"Pomodoro Technique","isCorrect":true},{"id":"17865149790073","text":"Feynman Technique","isCorrect":false},{"id":"1786515007432","text":"Active Recall Method","isCorrect":false}],"questionType":"Multiple Choice"}]}'::jsonb, '["batch1","batch1-lept","batch1-lept-bsed-english","batch1-lept-bsed-math","batch1-lept-bsed-science","batch1-lept-bsed-filipino","batch1-lept-bsed-socstudies","batch1-lept-beed","batch8","batch8-lept"]'::jsonb, NULL, 'active', 1, '2026-08-12T05:42:35.960Z', '2026-08-12T06:12:54.486Z') ON CONFLICT (id) DO NOTHING;
